class Solution {
    public String minWindow(String s, String t) {
        if (t.length() == 0) {
            return "";
        }
        int bestStart = -1;
        int bestLength = Integer.MAX_VALUE;
        int i = 0;
        while (i < s.length()) {
            int targetIndex = 0;
            while (i < s.length()) {
                if (s.charAt(i) == t.charAt(targetIndex)) {
                    targetIndex++;
                    if (targetIndex == t.length()) {
                        break;
                    }
                }
                i++;
            }
            if (i == s.length()) {
                break;
            }
            int end = i + 1;
            targetIndex = t.length() - 1;
            while (i >= 0) {
                if (s.charAt(i) == t.charAt(targetIndex)) {
                    targetIndex--;
                    if (targetIndex < 0) {
                        break;
                    }
                }
                i--;
            }
            int start = i;
            int length = end - start;
            if (length < bestLength) {
                bestLength = length;
                bestStart = start;
            }
            i = start + 1;
        }
        return bestStart == -1 ? "" : s.substring(bestStart, bestStart + bestLength);
    }
}

class Solution {
    public String minWindow(String s, String t) {
        if (t.length() == 0) {
            return "";
        }
        int n = s.length();
        int alphabet = 128;
        int[][] next = new int[n + 1][alphabet];
        java.util.Arrays.fill(next[n], -1);
        for (int i = n - 1; i >= 0; i--) {
            next[i] = next[i + 1].clone();
            int ch = s.charAt(i);
            if (ch < alphabet) {
                next[i][ch] = i;
            }
        }
        int bestStart = -1;
        int bestLength = Integer.MAX_VALUE;
        for (int start = 0; start < n; start++) {
            if (s.charAt(start) != t.charAt(0)) {
                continue;
            }
            int pos = start;
            boolean matched = true;
            for (int j = 0; j < t.length(); j++) {
                int ch = t.charAt(j);
                if (ch >= alphabet || next[pos][ch] == -1) {
                    matched = false;
                    break;
                }
                pos = next[pos][ch] + 1;
            }
            if (matched && pos - start < bestLength) {
                bestLength = pos - start;
                bestStart = start;
            }
        }
        return bestStart == -1 ? "" : s.substring(bestStart, bestStart + bestLength);
    }
}

class Solution {
    public String minWindow(String s, String t) {
        if (t.length() == 0) {
            return "";
        }
        int alphabet = 128;
        java.util.List<Integer>[] positions = new java.util.ArrayList[alphabet];
        for (int i = 0; i < s.length(); i++) {
            int ch = s.charAt(i);
            if (ch < alphabet) {
                if (positions[ch] == null) {
                    positions[ch] = new java.util.ArrayList<>();
                }
                positions[ch].add(i);
            }
        }
        int first = t.charAt(0);
        if (first >= alphabet || positions[first] == null) {
            return "";
        }
        int bestStart = -1;
        int bestLength = Integer.MAX_VALUE;
        for (int start : positions[first]) {
            int current = start;
            boolean matched = true;
            for (int j = 1; j < t.length(); j++) {
                int ch = t.charAt(j);
                if (ch >= alphabet || positions[ch] == null) {
                    matched = false;
                    break;
                }
                int index = upperBound(positions[ch], current);
                if (index == positions[ch].size()) {
                    matched = false;
                    break;
                }
                current = positions[ch].get(index);
            }
            int length = current - start + 1;
            if (matched && length < bestLength) {
                bestLength = length;
                bestStart = start;
            }
        }
        return bestStart == -1 ? "" : s.substring(bestStart, bestStart + bestLength);
    }

    private int upperBound(java.util.List<Integer> positions, int value) {
        int left = 0;
        int right = positions.size();
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (positions.get(mid) <= value) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

class Solution {
    public String minWindow(String s, String t) {
        if (t.length() == 0) {
            return "";
        }
        int m = t.length();
        int[] start = new int[m];
        java.util.Arrays.fill(start, -1);
        int bestStart = -1;
        int bestLength = Integer.MAX_VALUE;
        for (int i = 0; i < s.length(); i++) {
            for (int j = m - 1; j >= 0; j--) {
                if (s.charAt(i) != t.charAt(j)) {
                    continue;
                }
                if (j == 0) {
                    start[0] = i;
                } else if (start[j - 1] != -1) {
                    start[j] = start[j - 1];
                }
            }
            if (start[m - 1] != -1) {
                int length = i - start[m - 1] + 1;
                if (length < bestLength) {
                    bestLength = length;
                    bestStart = start[m - 1];
                }
            }
        }
        return bestStart == -1 ? "" : s.substring(bestStart, bestStart + bestLength);
    }
}

class Solution {
    public String minWindow(String s, String t) {
        if (t.length() == 0) {
            return "";
        }
        int n = s.length();
        int m = t.length();
        int[][] end = new int[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            end[i][m] = i;
        }
        for (int j = 0; j < m; j++) {
            end[n][j] = -1;
        }
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (s.charAt(i) == t.charAt(j)) {
                    end[i][j] = end[i + 1][j + 1];
                } else {
                    end[i][j] = end[i + 1][j];
                }
            }
        }
        int bestStart = -1;
        int bestLength = Integer.MAX_VALUE;
        for (int start = 0; start < n; start++) {
            if (s.charAt(start) != t.charAt(0)) {
                continue;
            }
            int finish = end[start][0];
            if (finish != -1 && finish - start < bestLength) {
                bestLength = finish - start;
                bestStart = start;
            }
        }
        return bestStart == -1 ? "" : s.substring(bestStart, bestStart + bestLength);
    }
}
